import unittest
from dups import find_duplicates


class Regression(unittest.TestCase):
    def test_each_listed_once(self):
        self.assertEqual(find_duplicates([1, 1, 1]), [1])

    def test_no_duplicates(self):
        self.assertEqual(find_duplicates([1, 2, 3]), [])

    def test_empty(self):
        self.assertEqual(find_duplicates([]), [])

